import{_ as e}from"./chunks/autonomous.DdFNL1Im.js";import{_ as o,o as a,c as r,a2 as s}from"./chunks/framework.CS-cBh1g.js";const b=JSON.parse('{"title":"Autonomous","description":"","frontmatter":{},"headers":[],"relativePath":"suite/autonomous.md","filePath":"suite/autonomous.md"}'),n={name:"suite/autonomous.md"};function d(i,t,h,l,c,g){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="autonomous" tabindex="-1">Autonomous <a class="header-anchor" href="#autonomous" aria-label="Permalink to &quot;Autonomous&quot;">​</a></h1><p>Build an auto by placing goals on the field, attach actions and conditions, then preview it.</p><p><img src="'+e+'" alt="The Autonomous workspace"></p><p>The header shows the step count and how much of the 15 s auto period the routine uses; the badge above the field says <strong>Fits in auto</strong>, how far over it is, <strong>Doesn&#39;t finish</strong>, or how many errors to fix.</p><p>Set the robot&#39;s size and limits on <a href="/Mayhem/suite/robot#specs-limits">Robot → Specs &amp; limits</a> first; every routine is planned with them. Field coordinates use the blue-alliance origin.</p><h2 id="routines" tabindex="-1">Routines <a class="header-anchor" href="#routines" aria-label="Permalink to &quot;Routines&quot;">​</a></h2><p>The left rail lists routines. Right-click one to open, rename, duplicate, delete or create a routine. Below it, the selected routine&#39;s steps appear in order:</p><ul><li><strong>Starting pose.</strong> Drag the robot and its heading handle on the field, or right-click → <strong>Edit starting pose</strong>. <strong>Use robot default start</strong> clears it.</li><li><strong>Steps.</strong> Drag to reorder, or right-click for <strong>Move up / down / to top</strong>, <strong>Duplicate</strong>, <strong>Add pose goal after</strong>, <strong>Add action after</strong>, <strong>Add custom C++ after</strong> and <strong>Delete step</strong>.</li></ul><h2 id="placing-goals" tabindex="-1">Placing goals <a class="header-anchor" href="#placing-goals" aria-label="Permalink to &quot;Placing goals&quot;">​</a></h2><p>Pick a tool above the field:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Key</th><th>Places</th></tr></thead><tbody><tr><td><strong>Select</strong></td><td><code>V</code> / <code>Esc</code></td><td>Nothing: click to select, drag to move. Double-click the field to add a pose.</td></tr><tr><td><strong>Pose</strong></td><td><code>W</code></td><td>A goal with a fixed heading. The robot settles there.</td></tr><tr><td><strong>Any heading</strong></td><td><code>T</code></td><td>A goal the robot reaches at whatever heading.</td></tr><tr><td><strong>Pass through</strong></td><td><code>G</code></td><td>A point the robot drives through without stopping.</td></tr><tr><td><strong>Draw</strong></td><td><code>D</code></td><td>Drag a route freehand; it becomes a few pass-through points and a final pose after the selected step. Hold Shift on release to keep the heading.</td></tr></tbody></table><p>Drag a goal&#39;s knob to turn it; Shift-drag snaps to 15°. Right-click a goal to turn, duplicate or delete it. When goals are stacked, click the stack to spread them out.</p><p>Routines with several legs show a strip above the field. Click a leg to focus it; the path is colored by speed.</p><h2 id="the-inspector" tabindex="-1">The inspector <a class="header-anchor" href="#the-inspector" aria-label="Permalink to &quot;The inspector&quot;">​</a></h2><p>The right panel has two tabs. Hide it with its close button and bring it back with <strong>Show inspector</strong>.</p><h3 id="selected-step" tabindex="-1">Selected step <a class="header-anchor" href="#selected-step" aria-label="Permalink to &quot;Selected step&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tab</th><th>What&#39;s there</th></tr></thead><tbody><tr><td><strong>Pose</strong></td><td>X, Y, heading, <strong>Stop here</strong>, and the handoff radius for pass-through points.</td></tr><tr><td><strong>Constraints</strong></td><td>Speed, acceleration and turn limits for driving to this step.</td></tr><tr><td><strong>Advanced</strong></td><td>Heading policy, markers, arrival tolerances, settle time, callback IDs, concurrent actions, transition conditions, branches, watchdog timeouts and failure behavior.</td></tr></tbody></table><p>A watchdog fails the routine when it runs out. On an action or custom step, <strong>Done when time runs out</strong> makes it a fixed window instead (for example, aim and shoot for 3.5 s, then continue). Callback IDs must be implemented in your robot code.</p><h3 id="whole-path" tabindex="-1">Whole path <a class="header-anchor" href="#whole-path" aria-label="Permalink to &quot;Whole path&quot;">​</a></h3><p>How fast this path moves and turns. Three views:</p><ul><li><strong>Map.</strong> Each segment&#39;s speed cap and handoff radius. Hatched blocks are <strong>Auto</strong>, solid blocks <strong>Manual</strong>; the last block says Stop. <strong>Generate</strong> solves speed caps and corner radii together (in the background, so you can keep editing). Click a block to select that segment, switch it to Manual to pin a value; Generate keeps pins. When poses or limits change the map says <strong>Path changed</strong> until you generate again. <strong>Review limits</strong> means a best-effort result; an unsolvable run asks you to change a manual value.</li><li><strong>Path limits.</strong> Max speed, acceleration, turn speed and turn acceleration, and the default handoff radius for this routine. They default to the robot&#39;s limits.</li><li><strong>Range.</strong> Apply only the values you change to a From/Through range of steps.</li></ul><p>Per-segment manual limits beat generated and path limits. Generated caps never raise a path limit you lowered.</p><h2 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h2><p>Press <strong>Preview</strong> (or Space) to play. The dock under the field has reset, a scrubber with event markers, and two modes:</p><table tabindex="0"><thead><tr><th>Mode</th><th>What it checks</th></tr></thead><tbody><tr><td><strong>Path</strong></td><td>Drives every pose on the first branch. Actions finish instantly and sensor conditions are skipped.</td></tr><tr><td><strong>With actions</strong></td><td>Runs actions and waits on inputs like the robot will: arrival, callback results, transition conditions and watchdogs.</td></tr></tbody></table><p>Open <strong>Inputs &amp; events</strong> to set simulated inputs and callback results, read the event list (click one to jump there) and see what the routine is waiting on. <strong>Freeze drivetrain</strong> keeps the robot still so you can watch a watchdog fail. <strong>Export trace JSON</strong> saves the mode, inputs, events and frames.</p><p>The preview is kinematic: it doesn&#39;t use PID gains, avoid obstacles or run your custom code. Point-at and motion heading policies and open-ended conditional handoffs use the measured-pose controller preview. Previews stop at 600 s or 1,000 events.</p><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><code>V</code> / <code>Esc</code>, <code>W</code>, <code>T</code>, <code>G</code>, <code>D</code></td><td>Select, Pose, Any heading, Pass through, Draw</td></tr><tr><td>Double-click</td><td>Add a pose</td></tr><tr><td>Right-click</td><td>Goal menu: turn, duplicate, delete</td></tr><tr><td>Shift + drag knob</td><td>Snap heading to 15°</td></tr><tr><td>Delete</td><td>Remove the selected step</td></tr><tr><td>⌘/Ctrl Z, ⇧⌘/Ctrl Z</td><td>Undo, redo</td></tr><tr><td><code>,</code> <code>.</code></td><td>Previous / next goal</td></tr><tr><td><code>[</code> <code>]</code></td><td>Previous / next leg</td></tr><tr><td>Drag</td><td>Pan the field</td></tr><tr><td>Space</td><td>Play or pause</td></tr><tr><td><code>?</code></td><td>Show the shortcut list</td></tr></tbody></table><h2 id="getting-it-on-the-robot" tabindex="-1">Getting it on the robot <a class="header-anchor" href="#getting-it-on-the-robot" aria-label="Permalink to &quot;Getting it on the robot&quot;">​</a></h2><p>The robot runs routines with Mayhem&#39;s C++ library. Export the C++ from <strong>Tasks → Connect an agent → C++ library</strong> (or the match-ready checklist on Overview), or generate it with <code>scripts/mayhem.mjs cpp</code>. Then bind your action and signal IDs in robot code and tune on the real robot; see <a href="/Mayhem/robot-code/autos">Running autos</a>. Exporting a header doesn&#39;t deploy anything.</p>',31)])])}const m=o(n,[["render",d]]);export{b as __pageData,m as default};
